//! Native attribute-list presence reads the genuine current Element storage.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><p id=target></p><svg id=svg></svg></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://dataset-inspection.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}

#[test]
fn attribute_list_presence_canonical_method_and_genuine_brand(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var m=Element.prototype.hasAttributes,desc=Object.getOwnPropertyDescriptor(Element.prototype,'hasAttributes'),n=document.createElement('p');if(typeof m!=='function'||m.name!=='hasAttributes'||m.length!==0||Object.hasOwn(m,'prototype')||desc.value!==m||!desc.writable||!desc.enumerable||!desc.configurable||Object.hasOwn(n,'hasAttributes'))throw 'canonical method metadata';for(var x of [{},Object.create(Element.prototype),document,null,undefined]){var error;try{m.call(x);}catch(e){error=e;}if(!(error instanceof TypeError))throw 'genuine Element brand';}if(m.call(n)!==false)throw 'brand recovery';"#);}

#[test]
fn attribute_list_presence_empty_nonempty_and_last_removal_are_live(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.createElement('p');if(n.hasAttributes()!==false)throw 'empty';n.setAttribute('data-a','');if(n.hasAttributes()!==true)throw 'empty value is present';n.setAttributeNS('urn:a','p:x','v');n.removeAttribute('data-a');if(!n.hasAttributes())throw 'namespaced attribute remains';n.removeAttributeNS('urn:a','x');if(n.hasAttributes())throw 'last native attribute removed';n.textContent='text';n.appendChild(document.createElement('span'));if(n.hasAttributes())throw 'children and text are not attributes';"#);}

#[test]
fn attribute_list_presence_main_and_inert_html_svg_xml_storage(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var inert=document.implementation.createHTMLDocument('inert'),xml=new Document();for(var n of [document.createElement('p'),document.createElementNS('http://www.w3.org/2000/svg','svg'),inert.createElement('p'),inert.createElementNS('http://www.w3.org/2000/svg','svg'),xml.createElement('item')]){if(n.hasAttributes())throw 'initial owner attributes';n.setAttributeNS(null,'data-a','');if(!n.hasAttributes())throw 'real owner attribute';n.removeAttributeNS(null,'data-a');if(n.hasAttributes())throw 'real owner last removal';}"#);}

#[test]
fn attribute_list_presence_attached_attr_identity_and_raw_payload_do_not_alias(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.createElement('p'),other=document.createElement('p');n.setAttributeNS(null,'data-x\ud800','raw\udfff');var a=n.getAttributeNodeNS(null,'data-x\ud800');if(!n.hasAttributes()||other.hasAttributes())throw 'actual native owners';n.removeAttributeNode(a);if(n.hasAttributes()||a.ownerElement!==null||a.value!=='raw\udfff')throw 'detached Attr is not an element attribute';other.setAttributeNode(a);if(!other.hasAttributes()||n.hasAttributes()||a.ownerElement!==other)throw 'actual Attr attachment';"#);}

#[test]
fn attribute_list_presence_ignores_arguments_and_author_method_shadows(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.createElement('p'),m=Element.prototype.hasAttributes,calls=0,value={toString:function(){calls++;throw 'must not convert';}};Object.defineProperty(value,'namespaceURI',{get:function(){calls++;throw 'must not inspect';}});if(m.call(n,value,Symbol('ignored'))!==false||calls)throw 'zero argument operation';n.setAttribute('data-a','');n.hasAttributes=function(){throw 'author shadow';};if(m.call(n,value)!==true||calls)throw 'saved native operation';"#);}

#[test]
fn attribute_list_presence_saved_child_method_uses_actual_receiver_and_error_realm(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var main=Element.prototype.hasAttributes,child=frame.contentWindow.Element.prototype.hasAttributes,n=document.createElement('p');if(typeof child!=='function'||child===main||child.length!==0||child.call(n)!==false)throw 'captured native roots';n.setAttribute('data-a','');if(child.call(n)!==true)throw 'actual receiver storage';var error;try{child.call({});}catch(e){error=e;}if(!(error instanceof frame.contentWindow.TypeError))throw 'child brand realm';"#);}

#[test]
fn attribute_list_presence_native_no_copy_work_deadline_refusal_and_recovery(){let(mut d,mut f,mut p)=fixture();let node=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("target")).unwrap();let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let retained=p.state.retained;for expired in [false,true]{p.begin_job();if expired{p.state.execution_deadline=Some(Instant::now());}else{p.state.host_work=0;}assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.call(node_handle(node),"hasAttributes",&[]).is_err());p.state.execution_deadline=None;p.begin_job();p.state.copy_work=0;p.state.retained=p.state.retained_limit;assert!(matches!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.call(node_handle(node),"hasAttributes",&[]).unwrap(),Value::Bool(true)));assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.retained=retained;}}
